// generar_270_rachas_sin_tope.js
// CHIQUI Entre Señales — Rachas ilimitadas (paseos y registros)
//
// PROBLEMA: cada racha tenía su propio tope invisible, distinto según
// dónde se calculara:
//   · Dashboard, racha de paseos ....... máximo 30 días
//   · Dashboard, racha de registros .... máximo 60 días
//   · Análisis, racha de paseos ........ máximo 200 días (y 6 meses
//     de datos cargados)
// El tope venía de dos lados a la vez: el bucle recorría un número
// fijo de días Y la consulta traía solo ese rango. Por eso una racha
// larga se quedaba pegada en el techo — y además el dashboard y
// Análisis podían mostrar números distintos para lo mismo.
//
// SOLUCIÓN: las tres ahora cuentan con un recorrido que termina solo
// cuando encuentra un hueco, sobre el historial completo (consulta de
// una o dos columnas, ordenada, hasta 2000 días ≈ 5,5 años).
//
// La regla NO cambia, solo deja de truncarse:
//   · Racha de PASEOS: días consecutivos con paseo efectivo. Un
//     registro diario sin paseo (o marcado "no paseó") NO la mantiene.
//   · Racha de REGISTROS: días consecutivos con registro diario,
//     haya paseo o no.
//   · En ambas, si hoy todavía no hay registro la racha no se pierde:
//     se cuenta desde ayer y queda "en riesgo" hasta que pase el día.
//
// DE PASO se corrigió una inconsistencia: el dashboard consideraba
// "paseó hoy" con que existiera cualquier registro del día, mientras
// Análisis exigía que ese registro tuviera paseo. Con un registro de
// hoy sin paseo, el dashboard mostraba 0 y Análisis mostraba la racha
// anterior en riesgo. Ahora ambos usan el criterio de Análisis.
//
// Detalle técnico: al retroceder un día se construye la fecha a las
// 12:00 en vez de restar 24 horas, para que los cambios de horario de
// verano de Chile (dos veces al año) no salten ni repitan un día.
//
// PENDIENTE (no incluido): el cron de notificaciones de racha en
// riesgo también tiene un tope de 40 días y por eso puede decir
// "¡Llevas 40 días seguidos!" a alguien que lleva 60. No lo toqué
// porque no quiero adivinar su ruta exacta en el proyecto y crear un
// archivo duplicado — confírmame la ruta y lo arreglo.
//
// No hay SQL.
//
// Uso:
//   node generar_270_rachas_sin_tope.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "app/dashboard/page.tsx",
    base64: ""
  },
  {
    ruta: "app/analisis/page.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 2 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
